package com.afterglow.player;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Bitmap;import java.io.*;
public class DeviceChecks extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}void check(boolean pass,String message){if(!pass)throw new AssertionError(message);android.util.Log.i("AfterglowTest","PASS: "+message);}
 public void onStart(){Bundle result=new Bundle();try{check(PlaylistParser.parse("title,artist\r\n\"Hello, World\",Artist",true).get(1)[0].equals("Hello, World"),"CSV quoted comma and CRLF");boolean malformed=false;try{PlaylistParser.parse("\"bad",true);}catch(IllegalArgumentException e){malformed=true;}check(malformed,"CSV malformed quote rejection");check(PlaylistParser.parse("One\nTwo",false).size()==2,"TXT line import");Intent i=new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);MainActivity activity=(MainActivity)startActivitySync(i);for(int n=0;n<50&&PlaybackService.instance==null;n++)Thread.sleep(100);PlaybackService s=PlaybackService.instance;check(s!=null,"Native activity binds playback service");runOnMainSync(()->s.play(0));for(int n=0;n<100&&!s.ready;n++)Thread.sleep(100);check(s.ready,"Bundled WAV prepared");runOnMainSync(()->{});check(s.playing(),"Native MediaPlayer playback starts");Thread.sleep(1200);check(s.position()>0,"Playback position advances");check(s.dsp!=null,"Device provides DynamicsProcessing");runOnMainSync(()->{s.gains[0]=6;s.gains[5]=-3;s.applyEQ();});check(s.dsp.getPreEqBandByChannelIndex(0,0).getGain()==6,"Bass gain applies to audio effect");check(s.dsp.getPreEqBandByChannelIndex(0,5).getGain()==-3,"Mid-band cut applies to audio effect");runOnMainSync(()->s.seek(20000));Thread.sleep(400);check(s.position()>=19500,"Seek changes native playback position");for(int page=0;page<4;page++){final int selected=page;runOnMainSync(()->{activity.page=selected;activity.render();});waitForIdleSync();check(activity.body.getChildCount()>0,"Native page "+page+" renders");}runOnMainSync(()->{activity.page=0;activity.render();activity.moveTaskToBack(true);});Thread.sleep(1500);check(s.playing(),"Playback continues with Activity backgrounded");runOnMainSync(()->s.pause(true));check(!s.playing(),"Pause stops playback");runOnMainSync(()->{for(int n=0;n<10;n++)s.gains[n]=0;s.applyEQ();s.seek(0);});runOnMainSync(()->activity.startActivity(i));Thread.sleep(800);Bitmap screen=getUiAutomation().takeScreenshot();if(screen!=null){File file=new File(getTargetContext().getExternalFilesDir(null),"native-home.png");try(FileOutputStream out=new FileOutputStream(file)){screen.compress(Bitmap.CompressFormat.PNG,100,out);}result.putString("screenshot",file.getAbsolutePath());}result.putString("result","PASS: parser, native launch, audio, seek, 10-band DSP, four screens, background playback, pause");finish(Activity.RESULT_OK,result);}catch(Throwable e){android.util.Log.e("AfterglowTest","FAILED",e);result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}}
}


